do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-059","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"ref":"w0","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL14877416W"},"before":null,"after":{"title":"Lady Windermere''s fan","author_id":977300022,"first_publish_year":1893,"open_library_id":"OL14877416W","cover_id":null,"source_type":"open_library","work_type":null,"native_identity_key":"nlscale:20261102:ol:OL14877416W","id":987158001}},{"ref":"e0","relation":"editions","key":{"open_library_edition_id":"OL12852236M"},"before":null,"after":{"work_id":"@w0","open_library_edition_id":"OL12852236M","isbn_13":"9789077932018","isbn_10":null,"title":"Lady Windermere''s Waaier","language":"dut","publisher":"Uitgeverij Diderot","id":987258001,"publish_date":null,"cover_id":null}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":"@w0","language":"nl"},"before":null,"after":{"work_id":"@w0","language":"nl","bound_author_id":977300022,"text":"Lady Windermere bereidt een feest voor haar verjaardag voor wanneer zij hoort dat haar man geld geeft aan een raadselachtige vrouw. Zijn ontkenning neemt haar argwaan niet weg. Als mevrouw Erlynne vervolgens op het bal verschijnt, dreigen jaloezie en gekrenkte trots haar huwelijk te ontwrichten. Lord Darlington biedt een uitweg die nieuwe risico’s meebrengt. In deze toneelkomedie botsen de keurige regels van de Londense samenleving met wat mensen werkelijk doen. Een verloren waaier kan daarbij meer onthullen dan een openhartig gesprek.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://data.bibliotheken.nl/id/nbt/p277353548","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p277353548"],"reference":"new-work-dossier-readings-059.json#173","checked_at":"2026-11-03T12:02:51.451Z","note":"OscarWilde four-act stageplay, not novel or adaptation. ExactDutchPaperback97890779